import java.io.PrintWriter;
import java.util.*;

public class Main {
    static int n;
    static long m;
    static long[] a;
    static boolean[] selected;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        m = in.nextInt();
        PrintWriter out = new PrintWriter(System.out);

        if (w <= 3) {
            out.print("YES\n");
            out.flush();
            return;
        }

        long limit = 10000000000L;
        List<Long> list = new ArrayList<>();
        long x = 1;
        do {
            list.add(x);
            x *= w;
        } while (x <= limit);

        n = list.size();
        a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = list.get(i);
        }
        selected = new boolean[n];

        out.print(dfs(0) ? "YES\n" : "NO\n");
        out.flush();
    }

    static boolean dfs(int idx) {
        if (idx == n) {
            long v = m;
            for (int j = 0; j < n; j++) {
                if (selected[j]) {
                    v += a[j];
                }
            }
            for (int j = n - 1; j >= 0; j--) {
                if (!selected[j] && v - a[j] >= 0) {
                    v -= a[j];
                }
            }
            return v == 0;
        }

        selected[idx] = false;
        if (dfs(idx + 1)) {
            return true;
        }
        selected[idx] = true;
        return dfs(idx + 1);
    }
}
